#!/usr/bin/env python3
"""Rebuild js/changes-data.js (the public corrections log) from every applied fact-check file in factcheck/."""
import json, glob, os
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'); os.chdir(ROOT)
AREA = {'js/marx-data.js': ['Marxism–Leninism deep dive', 'history-modern-marxism'], 'js/anatomy2.js': ['Anatomy of power', 'history-modern-anatomy'], 'js/modern-m.js': ['Anatomy of power', 'history-modern-anatomy'], 'js/usp-data.js': ['How American power works', 'history-modern-uspower'], 'js/usp-data2.js': ['How American power works', 'history-modern-uspower'], 'js/korea-data.js': ['The Korean War', 'history-modern-koreawar'], 'js/power-data.js': ['Who really rules?', 'history-modern-power'], 'js/africa-data.js': ['Africa in depth', 'history-modern-africa'], 'js/americas-data.js': ['The Americas in depth', 'history-modern-americas'], 'js/modern-j.js': ['People', 'history-modern-people'], 'js/modern-c.js': ['Events', 'history-modern-events']}
done = json.load(open('factcheck/applied.json')); out = []
for f in sorted(glob.glob('factcheck/*.json')):
    n = os.path.basename(f)[:-5]
    if n not in done or n == 'applied': continue
    data = json.load(open(f, encoding='utf-8'))
    if not isinstance(data, list) or not data or 'old' not in data[0]: continue  # claim-verification files are logged via the claim records
    for it in data:
        a = AREA.get(it['file'], [it.get('area') or it['file'], it.get('page', '')])
        out.append({'d': done[n], 'area': a[0], 'page': a[1], 'sev': it.get('severity', 'error'), 'what': it['problem'], 'src': it.get('sources', [])[:3]})
out.sort(key=lambda x: x['d'], reverse=True)
open('js/changes-data.js', 'w', encoding='utf-8').write('/* Public corrections log, generated by tools/mkchanges.py from factcheck/. */\nLab.CHANGES = ' + json.dumps(out, ensure_ascii=False, indent=0) + ';\n')
print(len(out), 'corrections in the log')
